		LuaEvent::Queue("onShipDocked", dt.ship, this);
		m_doorAnimationStep = -0.3; // close door
		dt.ship->SetDockedWith(this, bay);
		break;
	}

	case DockStage::UNDOCK_BEGIN:
		if (m_type->NumUndockStages() > 0) {
